/*
 * A036586  Ternary Thue-Morse sequence: closed under a->abc, b->ac, c->b.
 * https://oeis.org/A036586
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Recurrence: a(0)=2, generated by the fixed point of the morphism
   a→abc, b→ac, c→b (a=2, b=0, c=1). */

#include <stddef.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of the prefix of the fixed point */
    static seq_t *seq = NULL;   /* array holding the symbols so far   */
    static size_t len = 0;      /* number of elements currently stored */

    /* initialise the seed word "a" mapped to the value 2 */
    if (seq == NULL)
    {
        seq = (seq_t *)malloc(sizeof(seq_t));
        if (!seq) return (seq_t)0; /* fallback – should not happen */
        seq[0] = 2;
        len   = 1;
    }

    /* grow the word until it contains at least n+1 symbols */
    while (len <= n)
    {
        /* the maximal growth factor of one expansion step is 3 */
        size_t new_cap = len * 3;
        seq_t *next = (seq_t *)malloc(new_cap * sizeof(seq_t));
        if (!next) return (seq_t)0; /* fallback – should not happen */

        size_t dst = 0;
        for (size_t i = 0; i < len; ++i)
        {
            seq_t v = seq[i];
            if (v == 2)          /* a → abc → 2,0,1 */
            {
                next[dst++] = 2;
                next[dst++] = 0;
                next[dst++] = 1;
            }
            else if (v == 0)     /* b → ac  → 2,1 */
            {
                next[dst++] = 2;
                next[dst++] = 1;
            }
            else /* v == 1 */    /* c → b   → 0 */
            {
                next[dst++] = 0;
            }
        }

        free(seq);           /* discard the previous prefix   */
        seq = next;          /* keep the expanded prefix      */
        len = dst;           /* the new length of the prefix  */
    }

    return seq[n];
}
